-- ConviteIA — Temas 2.0
-- Execute no SQL Editor do Supabase antes de publicar convites usando as novas paletas.
-- É idempotente: pode ser executado novamente sem duplicar temas.

on conflict (id) do update set
  nome = excluded.nome,
  variante_layout = excluded.variante_layout,
  tokens = excluded.tokens,
  ordem = excluded.ordem,
  ativo = true;
